namespace nativebridge::detail {

class WaylandWindow;

/// evdev scancode -> X11 keysym. Shared with the X11 backend's mapping table so
/// both Linux backends report identical KeyCode values.
[[nodiscard]] uint32_t waylandKeysymFromEvdev(uint32_t evdev) noexcept;

/// evdev scancode -> KeyCode (thin wrapper over the shared keysym mapping).
[[nodiscard]] KeyCode waylandKeyCodeFromEvdev(uint32_t evdev) noexcept;

/// evdev scancode -> character, 0 when the key produces no text.
[[nodiscard]] uint32_t waylandCharacterFromEvdev(uint32_t evdev) noexcept;

/// Wayland keyboard state value (WL_KEYBOARD_KEY_STATE_PRESSED).
[[nodiscard]] inline bool waylandKeyIsPressed(uint32_t state) noexcept {
    return state == WL_KEYBOARD_KEY_STATE_PRESSED;
}

/// One wl_output plus the state the server reports about it.
struct WaylandOutputState {
    uint32_t   globalName{0}; ///< wl_registry name, used for hotplug removal.
    wl_output* output{nullptr};
    DisplayInfo info{};
    Point      logicalOrigin{0, 0}; ///< Documented layout origin (see rebuildDisplays).
    int32_t    pixelWidth{0};
    int32_t    pixelHeight{0};
    uint32_t   refreshMilliHz{0};
    uint32_t   scale{1};
    bool       hasMode{false};
    bool       done{false};
};

/// The Wayland PlatformBackend implementation.
class WaylandPlatform final : public PlatformBackend {
public:
    WaylandPlatform();
    ~WaylandPlatform() override;

    [[nodiscard]] std::string_view name() const noexcept override { return "wayland"; }
    [[nodiscard]] bool supports(Capability capability) const noexcept override;
    [[nodiscard]] std::string describe() const override;

    void pump() override;
    std::size_t wait(std::chrono::milliseconds timeout) override;
    [[nodiscard]] std::vector<Event> takeEvents() override { return m_queue.drain(); }

    void refreshDisplays() override;
    [[nodiscard]] const DisplayList& displays() const noexcept override { return m_displays; }

    [[nodiscard]] Result<std::unique_ptr<WindowBackend>> createWindow(const WindowCreateInfo& info) override;
    [[nodiscard]] Clipboard& clipboard() override;
    void destroyWindow(WindowBackend* window) override;
    [[nodiscard]] std::optional<Error> fatalError() const override { return m_fatal; }

    // --- Accessors used by WaylandWindow -----------------------------------
    [[nodiscard]] wl_display* display() const noexcept { return m_display; }
    [[nodiscard]] wl_compositor* compositor() const noexcept { return m_compositor; }
    [[nodiscard]] wl_shm* shm() const noexcept { return m_shm; }
    [[nodiscard]] wl_seat* seat() const noexcept { return m_seat; }
    [[nodiscard]] wl_data_device* dataDevice() const noexcept { return m_dataDevice; }
#ifdef NATIVEBRIDGE_HAVE_XDG_SHELL
    [[nodiscard]] xdg_wm_base* wmBase() const noexcept { return m_wmBase; }
#endif
    [[nodiscard]] bool hasXdgShell() const noexcept { return m_hasXdgShell; }
    [[nodiscard]] EventQueue& queue() noexcept { return m_queue; }
    [[nodiscard]] WindowId nextWindowId() noexcept { return m_nextWindowId++; }
    [[nodiscard]] WeakLifetimeToken lifetime() const noexcept { return m_lifetime; }
    [[nodiscard]] bool isUiThread() const noexcept { return std::this_thread::get_id() == m_uiThread; }
    [[nodiscard]] int scrollLinesPerNotch() const noexcept { return m_scrollLinesPerNotch; }

    /// Highest scale factor reported by any output (Wayland has no per-window
    /// scale until a surface has entered an output).
    [[nodiscard]] double sessionScaleFactor() const noexcept { return m_scale; }

    void windowDestroyed(WindowId id);
    [[nodiscard]] std::size_t dispatchPending();

    // --- Registry / output / seat handling ---------------------------------
    void handleGlobal(wl_registry* registry, uint32_t name, const char* interface, uint32_t version);
    void handleGlobalRemove(uint32_t name);
    void markDisplaysDirty() { m_displaysDirty = true; }
    void onOutputMode(uint32_t flags, int32_t width, int32_t height, int32_t refreshMilliHz);
    void onOutputScale(int32_t factor);
    void onOutputName(const char* name);
    void onOutputDescription(const char* description);
    void onSeatCapabilities(wl_seat* seat, uint32_t capabilities);
    /// Small helper used by WaylandWindow while creating its surface.
    [[nodiscard]] const std::vector<WaylandOutputState>& outputsForWindow() const noexcept { return m_outputs; }

    // --- Input routing -----------------------------------------------------
    [[nodiscard]] WaylandWindow* windowForSurface(wl_surface* surface) const;
    void setPointerFocus(WaylandWindow* window, uint32_t enterSerial);
    void onPointerPosition(double x, double y);
    void onPointerLeave();
    void onPointerButton(uint32_t button, uint32_t state);
    void onPointerAxis(uint32_t axis, double value, bool discrete);
    void onPointerAxisDiscrete(uint32_t axis, int32_t steps);
    void setAxisSource(uint32_t axisSource) { m_axisSource = axisSource; }
    void flushPointerEvents();
    void onKeyboardFocus(WaylandWindow* window, bool entered);
    void onKeyboardKey(uint32_t evdevKey, uint32_t state);
    void onKeyboardModifiers(uint32_t depressed, uint32_t locked);
    void rememberSerial(uint32_t serial) noexcept { m_lastSerial = serial; }
    [[nodiscard]] uint32_t lastSerial() const noexcept { return m_lastSerial; }
    [[nodiscard]] WaylandWindow* pointerFocus() const noexcept { return m_pointerFocus; }

    // --- Clipboard ---------------------------------------------------------
    [[nodiscard]] Result<std::string> clipboardGetText();
    [[nodiscard]] Status clipboardSetText(std::string_view utf8Text);
    [[nodiscard]] Status clipboardClear();
    [[nodiscard]] bool clipboardHasText();
    void onSelectionOffer(wl_data_offer* offer);
    /// Called from the wl_data_offer listener for every advertised flavour.
    void onDataOfferMimeType(const char* mimeType);
    void onDataSourceSend(const char* mimeType, int32_t fd);
    void onDataSourceCancelled(wl_data_source* source);
    [[nodiscard]] bool hasKeyboardFocus() const noexcept { return m_keyboardFocusWindow != 0; }

    void trackPressedButton(uint32_t button, bool pressed);
    [[nodiscard]] bool anyButtonPressed() const noexcept { return m_pressedButtons != 0; }
    [[nodiscard]] Modifier modifiers() const noexcept { return m_modifiers; }
    [[nodiscard]] Point pointerPosition() const noexcept { return m_pointerPosition; }

private:
    void connect();
    void rebuildDisplays();
    void destroySeatObjects();

    wl_display*    m_display{nullptr};
    wl_registry*   m_registry{nullptr};
    wl_compositor* m_compositor{nullptr};
    wl_shm*        m_shm{nullptr};
    wl_seat*       m_seat{nullptr};
    wl_pointer*    m_pointer{nullptr};
    wl_keyboard*   m_keyboard{nullptr};
    wl_data_device_manager* m_dataDeviceManager{nullptr};
    wl_data_device*         m_dataDevice{nullptr};
#ifdef NATIVEBRIDGE_HAVE_XDG_SHELL
    xdg_wm_base* m_wmBase{nullptr};
#endif
    std::vector<WaylandOutputState> m_outputs;

    WaylandWindow* m_pointerFocus{nullptr};
    WaylandWindow* m_keyboardFocusWindow{nullptr};
    uint32_t m_enterSerial{0};
    uint32_t m_lastSerial{0};
    uint32_t m_axisSource{0};
    Modifier m_modifiers{Modifier::None};
    Point    m_pointerPosition{0, 0};
    double   m_pendingScrollX{0.0};
    double   m_pendingScrollY{0.0};
    bool     m_pendingScrollPrecise{false};
    uint32_t m_pressedButtons{0};

    bool   m_hasXdgShell{false};
    bool   m_displaysDirty{true};
    double m_scale{1.0};
    int    m_scrollLinesPerNotch{3};

    EventQueue                 m_queue;
    DisplayList                m_displays;
    std::unique_ptr<Clipboard> m_clipboardFacade;
    LifetimeTokenPtr           m_lifetime{std::make_shared<LifetimeToken>()};
    std::optional<Error>       m_fatal;
    std::thread::id            m_uiThread{std::this_thread::get_id()};
    WindowId                   m_nextWindowId{1};
    std::mutex                 m_windowsMutex;
    std::vector<WaylandWindow*> m_windows;

    // Clipboard state.
    wl_data_offer*  m_selectionOffer{nullptr}; ///< Current CLIPBOARD offer.
    wl_data_source* m_dataSource{nullptr};     ///< Our offer while we own it.
    std::string     m_selectionMimeType;       ///< Chosen flavour of the offer.
    std::string     m_ownClipboardText;        ///< Text we serve as owner.
    bool            m_offerHasText{false};
    bool            m_ownSelection{false};

    friend class WaylandWindow;
};

/// The Wayland window backend: wl_surface + xdg_surface + xdg_toplevel.
class WaylandWindow final : public WindowBackend {
public:
    WaylandWindow(WaylandPlatform& platform, WindowId id, const WindowCreateInfo& info);
    ~WaylandWindow() override;

    WaylandWindow(const WaylandWindow&) = delete;
    WaylandWindow& operator=(const WaylandWindow&) = delete;

    [[nodiscard]] WindowId id() const noexcept override { return m_id; }
    [[nodiscard]] bool supports(Capability capability) const noexcept override;
    [[nodiscard]] std::string_view backendName() const noexcept override { return "wayland"; }

    [[nodiscard]] std::string title() const override { return m_title.get(); }
    [[nodiscard]] Size clientSize() const override { return m_clientSize.get(); }
    /// The compositor owns the decoration, so windowSize() == clientSize().
    [[nodiscard]] Size windowSize() const override { return m_clientSize.get(); }
    /// Always {0,0}: Wayland never reveals a global position.
    [[nodiscard]] Point position() const override { return Point{0, 0}; }
    [[nodiscard]] PixelSize framebufferSize() const override {
        return logicalToPhysical(m_clientSize.get(), m_scaleFactor.get());
    }
    [[nodiscard]] double scaleFactor() const override { return m_scaleFactor.get(); }
    [[nodiscard]] bool isVisible() const override { return m_visible.get(); }
    [[nodiscard]] bool isFocused() const override { return m_focused.get(); }
    [[nodiscard]] bool isMinimized() const override { return m_minimized.get(); }
    [[nodiscard]] bool isMaximized() const override { return m_maximized.get(); }
    [[nodiscard]] bool isFullscreen() const override { return m_fullscreen.get(); }
    [[nodiscard]] CursorShape cursor() const override { return m_cursor.get(); }
    [[nodiscard]] WindowNativeHandle nativeHandle() const override;

    [[nodiscard]] Status setTitle(std::string_view title) override;
    [[nodiscard]] Status resize(Size clientSize) override;
    /// Always Err::Unsupported: Wayland has no global positioning request.
    [[nodiscard]] Status move(Point position) override;
    [[nodiscard]] Status setMinSize(Size size) override;
    [[nodiscard]] Status setMaxSize(Size size) override;
    [[nodiscard]] Status show() override;
    [[nodiscard]] Status hide() override;
    [[nodiscard]] Status minimize() override;
    [[nodiscard]] Status maximize() override;
    [[nodiscard]] Status restore() override;
    [[nodiscard]] Status setFullscreen(bool fullscreen) override;
    [[nodiscard]] Status setAlwaysOnTop(bool onTop) override;
    /// Compositor owned decorations: Err::Unsupported.
    [[nodiscard]] Status setDecorations(bool decorations) override;
    [[nodiscard]] Status setResizable(bool resizable) override;
    [[nodiscard]] Status setCursor(CursorShape shape) override;
    [[nodiscard]] Status setCursorVisible(bool visible) override;
    [[nodiscard]] Status setClipRect(const std::optional<Rect>& rect) override;
    [[nodiscard]] Status requestAttention() override;
    [[nodiscard]] Status requestClose() override;
    /// Needs libwayland-cursor (excluded by the dependency constraint).
    [[nodiscard]] Status setCustomCursor(std::span<const uint8_t> bgraPixels, Size size, Point hotspot) override;
    [[nodiscard]] Status materializeSurface(RenderApi api, std::string_view backendName,
                                            NativeHandle& surface) override;
    void onSurfaceResized() override;
    void onDisplayConfigurationChanged() override;
    void onNativeDestroyed() override;

    // --- Protocol callbacks (invoked by the platform's listeners) ----------
    void onConfigure(int32_t width, int32_t height, bool maximized, bool fullscreen, bool resizing);
    void onCloseRequested();
    void onEnterOutput(const WaylandOutputState& output);
    void onPointerEnterSerial(uint32_t serial) noexcept { m_lastEnterSerial = serial; }

    [[nodiscard]] wl_surface* surface() const noexcept { return m_surface; }
    [[nodiscard]] bool isDestroyed() const noexcept { return m_destroyed; }

private:
    void createSurface();
    void destroySurface();
    void pushResize();

    WaylandPlatform& m_platform;
    WindowId         m_id{0};
    wl_surface*      m_surface{nullptr};
#ifdef NATIVEBRIDGE_HAVE_XDG_SHELL
    xdg_surface*     m_xdgSurface{nullptr};
    xdg_toplevel*    m_toplevel{nullptr};
#endif
    bool   m_configured{false};
    bool   m_destroyed{false};
    bool   m_fullscreenActive{false};
    bool   m_maximizedActive{false};
    Size   m_minSize{0, 0};
    Size   m_maxSize{0, 0};
    CursorShape m_cursorShape{CursorShape::Arrow};
    bool   m_cursorVisible{true};
    double m_lastScale{1.0};
    uint32_t m_lastEnterSerial{0};
    std::optional<Rect> m_clipRect{};
    int32_t m_pendingWidth{0};
    int32_t m_pendingHeight{0};

    Snapshot<std::string> m_title{std::string{"nativeBridge window"}};
    Snapshot<Size>        m_clientSize{Size{0, 0}};
    Snapshot<double>      m_scaleFactor{1.0};
    Snapshot<bool>        m_visible{false};
    Snapshot<bool>        m_focused{false};
    Snapshot<bool>        m_minimized{false};
    Snapshot<bool>        m_maximized{false};
    Snapshot<bool>        m_fullscreen{false};
    Snapshot<CursorShape> m_cursor{CursorShape::Arrow};
};

} // namespace nativebridge::detail
